import React, { useState, useRef } from "react";
import axios from "axios";
import { motion } from "framer-motion";
import PageWrapper from "../components/PageWrapper";

const Interview = () => {
  const [videoFile, setVideoFile] = useState(null);
  const [recording, setRecording] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const [stream, setStream] = useState(null);
  const videoRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunks = useRef([]);

  // 📹 Start camera recording
  const startRecording = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      setStream(mediaStream);
      videoRef.current.srcObject = mediaStream;
      const mediaRecorder = new MediaRecorder(mediaStream);
      mediaRecorderRef.current = mediaRecorder;

      recordedChunks.current = [];
      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) recordedChunks.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const blob = new Blob(recordedChunks.current, { type: "video/mp4" });
        const file = new File([blob], "interview.mp4", { type: "video/mp4" });
        setVideoFile(file);
        setStream(null);
      };

      mediaRecorder.start();
      setRecording(true);
      setMessage("Recording started...");
    } catch (error) {
      console.error("Camera error:", error);
      setMessage("❌ Unable to access camera or microphone.");
    }
  };

  // 🛑 Stop recording
  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      stream.getTracks().forEach((track) => track.stop());
      setRecording(false);
      setMessage("🎥 Recording stopped. You can now upload.");
    }
  };

  // 📁 Handle manual file upload
  const handleFileChange = (e) => {
    setVideoFile(e.target.files[0]);
    setMessage("🎬 Video selected: " + e.target.files[0].name);
  };

  // ☁️ Upload to backend
  const handleUpload = async () => {
    if (!videoFile) {
      setMessage("Please record or select a video first!");
      return;
    }

    const formData = new FormData();
    formData.append("file", videoFile);

    try {
      setUploading(true);
      const res = await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setMessage("✅ Video uploaded successfully!");
    } catch (err) {
      console.error(err);
      setMessage("❌ Upload failed!");
    } finally {
      setUploading(false);
    }
  };

  return (
    <PageWrapper>
      <div className="flex flex-col items-center justify-center min-h-[80vh] bg-gradient-to-br from-gray-50 to-blue-50 px-4 py-8">
        <motion.h1
          initial={{ opacity: 0, y: -30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-3xl font-bold text-gray-800 mb-6"
        >
          Record or Upload Your Interview
        </motion.h1>

        {/* Camera Preview */}
        {stream && (
          <video
            ref={videoRef}
            autoPlay
            muted
            className="w-[500px] rounded-lg shadow-lg border border-gray-300 mb-6"
          />
        )}

        {/* Buttons */}
        <div className="flex flex-wrap gap-4 justify-center mb-6">
          {!recording && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={startRecording}
              className="bg-blue-600 text-white px-6 py-2 rounded-lg shadow-md hover:bg-blue-700 transition-all"
            >
              🎥 Start Recording
            </motion.button>
          )}

          {recording && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={stopRecording}
              className="bg-red-600 text-white px-6 py-2 rounded-lg shadow-md hover:bg-red-700 transition-all"
            >
              🛑 Stop Recording
            </motion.button>
          )}

          <label className="cursor-pointer bg-gray-100 px-6 py-2 rounded-lg border border-gray-300 hover:bg-gray-200 transition-all">
            📁 Choose File
            <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
          </label>

          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={handleUpload}
            disabled={uploading}
            className="bg-green-600 text-white px-6 py-2 rounded-lg shadow-md hover:bg-green-700 transition-all"
          >
            {uploading ? "Uploading..." : "☁️ Upload Video"}
          </motion.button>
        </div>

        {message && <p className="text-lg text-gray-700">{message}</p>}
      </div>
    </PageWrapper>
  );
};

export default Interview;
